const llmItems = $input.all();
const topic = $('Get available').first().json;

const classifications = llmItems.find(({ json }) =>
  Array.isArray(json.output?.classifications),
)?.json.output.classifications;

const originalItems = Object.values(
  $('Scrapper').first().json.items ?? {},
);

if (!classifications) {
  throw new Error('No se encontraron las clasificaciones');
}

const originalById = new Map(
  originalItems.map((item) => [String(item.id), item]),
);
const classifiedIds = new Set();
const classifiedAt = new Date().toISOString();

const classifiedItems = classifications.map(({ id, label, hasIrony }) => {
  const identifier = String(id);
  const original = originalById.get(identifier);

  if (!original) {
    throw new Error(`No se encontró la publicación con ID ${identifier}`);
  }

  if (classifiedIds.has(identifier)) {
    throw new Error(`ID repetido en la clasificación: ${identifier}`);
  }

  if (!['POS', 'NEG', 'NEU'].includes(label)) {
    throw new Error(`Sentimiento inválido: ${label}`);
  }

  if (typeof hasIrony !== 'boolean') {
    throw new Error(`hasIrony inválido para el ID ${identifier}`);
  }

  classifiedIds.add(identifier);
  const { id: _, ...publication } = original;

  return {
    ...publication,
    identifier,
    sentiment_llm: label,
    hasIrony,
    llm_model: $env.MODEL,
    llm_prompt_version: '4',
    llm_classified_at: classifiedAt,
  };
});

const missingIds = [...originalById.keys()].filter((id) => !classifiedIds.has(id));
if (missingIds.length) {
  throw new Error(`Faltan clasificaciones para los IDs: ${missingIds.join(', ')}`);
}

return [
  {
    json: {
      id: topic.id,
      empty_streak: topic.empty_streak,
      topic_id: topic.topic_id,
      name: topic.name,
      page: topic.page,
      items: classifiedItems,
    },
  },
];

const topic = $('Get available').first().json;

return [
  {
    json: {
      id: topic.id,
      empty_streak: topic.empty_streak,
      topic_id: topic.topic_id,
      name: topic.name,
      page: topic.page,
      items: [],
    },
  },
];
